import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.CdvW4CUT.js";const _=JSON.parse('{"title":"CLI 用法","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cli.md","filePath":"guide/cli.md","lastUpdated":1793803670000}'),r={name:"guide/cli.md"};function a(l,t,s,i,p,n){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="cli-用法" tabindex="-1">CLI 用法 <a class="header-anchor" href="#cli-用法" aria-label="Permalink to &quot;CLI 用法&quot;">​</a></h1><p>所有入口都走同一个可执行文件，用 flag 切换行为：</p><table tabindex="0"><thead><tr><th>Flag</th><th>说明</th></tr></thead><tbody><tr><td><code>-tui</code></td><td>启动终端 UI（默认若未指定其它模式）</td></tr><tr><td><code>-web</code></td><td>启动 Web UI（浏览器访问）</td></tr><tr><td><code>-e &quot;&lt;prompt&gt;&quot;</code></td><td>headless 模式：发送一条消息并跑完一轮</td></tr><tr><td><code>-s &lt;id&gt;</code></td><td>恢复指定会话并进入终端 UI（回放历史 + 继续）</td></tr><tr><td><code>--fork &lt;id&gt;</code></td><td>以某会话为蓝本派生新会话后进入</td></tr><tr><td><code>-view &lt;id&gt;</code></td><td>以只读浏览模式进入终端 UI</td></tr><tr><td><code>-replay &lt;id&gt;</code></td><td>非交互回放某会话的事件流（Trajectory 视图），打印后退出</td></tr><tr><td><code>-replay &lt;id&gt; -w</code></td><td>打印该会话的 Web 只读分享链接，不输出正文</td></tr><tr><td><code>-ls</code></td><td>列出全部会话（id / 时间 / 条数 / 标题）</td></tr><tr><td><code>-tools</code></td><td>打印当前 shell / 已启用工具 / 技能清单</td></tr><tr><td><code>-v</code></td><td>打印版本与已加载插件</td></tr><tr><td><code>-cfg &lt;path&gt;</code></td><td>指定配置文件路径（默认 <code>./config.json</code>）</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">示例</p><p><code>./gsh -replay 20260101-120000-ab12 -w</code> 会输出 <code>https://gsh.zgric.top/#/share/20260101-120000-ab12</code>（前提是 Web UI 自托管的分享域名，见<a href="./sessions.html#回放--分享">会话管理</a>）。</p></div>',4)])])}const g=d(r,[["render",a]]);export{_ as __pageData,g as default};
